return [{ json: {
  supabase_url: 'https://jaeltkzfjgrzgxgzxlfs.supabase.co',
  workspace_id: 'a51b8277-4cd5-4f8a-9ffd-4ddbe56683da',
  country: 'India',
  registry_source_url: 'https://www.sebi.gov.in/sebiweb/other/OtherAction.do?doRecognisedFpi=yes&intmId=21',
  registry_export_url: 'https://www.sebi.gov.in/sebiweb/other/IntmExportAction.do?intmId=21',
  registry_version: 'sebi-vcf-registry-v1.0.0',
  max_rows: 500
} }];

const config = $('SEBI Registry Configuration').first().json;

const inputRows = $input
  .all()
  .map((item) => item.json ?? {})
  .filter((row) => row && Object.keys(row).length > 0);

const maxRows = Math.max(
  1,
  Math.min(1000, Number(config.max_rows ?? 500))
);

const clean = (value, max = 2000) =>
  String(value ?? '')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, max);

const normalize = (value) =>
  clean(value)
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();

const aliases = {
  name: ['name', 'fund name', 'venture capital fund name'],
  registration_number: [
    'registration no.',
    'registration no',
    'registration number',
    'registration'
  ],
  contact_person: ['contact person', 'contact'],
  address: ['address'],
  correspondence_address: ['correspondence address'],
  email: ['email-id', 'email id', 'email', 'e mail id'],
  telephone: ['telephone', 'telephone no', 'phone', 'phone no'],
  fax: ['fax'],
  city: ['city'],
  state: ['state'],
  pincode: ['pincode', 'pin code', 'postal code'],
  validity: ['validity'],
  from: ['from', 'registration from'],
  to: ['to', 'registration to']
};

const matchesAlias = (value, aliasList) => {
  const normalized = normalize(value);
  return aliasList.some((alias) => {
    const a = normalize(alias);
    return normalized === a || normalized.includes(a);
  });
};

// SEBI's XLS export can contain title/header rows before the actual
// table header. The n8n XLS extractor may represent those headers as
// "__EMPTY", "__EMPTY_1", etc. Detect the real header row from its values.
const headerScore = (row) => {
  const values = Object.values(row).map(normalize).filter(Boolean);
  let score = 0;

  for (const aliasesForField of Object.values(aliases)) {
    if (values.some((value) => aliasesForField.some((alias) => {
      const a = normalize(alias);
      return value === a || value.includes(a);
    }))) {
      score++;
    }
  }

  return score;
};

let headerIndex = -1;
let bestHeaderScore = 0;

for (let i = 0; i < inputRows.length; i++) {
  const score = headerScore(inputRows[i]);
  if (score > bestHeaderScore) {
    bestHeaderScore = score;
    headerIndex = i;
  }
}

if (headerIndex < 0 || bestHeaderScore < 2) {
  throw new Error(
    `SEBI_HEADER_ROW_NOT_FOUND. Could not identify the table header. ` +
    `Best score=${bestHeaderScore}.`
  );
}

const headerRow = inputRows[headerIndex];

// Map canonical fields to the actual source keys used by the extractor.
const sourceKeyFor = (field) => {
  const candidates = aliases[field] ?? [];
  const entry = Object.entries(headerRow).find(([, value]) =>
    candidates.some((alias) => matchesAlias(value, [alias]))
  );
  return entry?.[0] ?? null;
};

const sourceKeys = {
  name: sourceKeyFor('name'),
  registration_number: sourceKeyFor('registration_number'),
  contact_person: sourceKeyFor('contact_person'),
  address: sourceKeyFor('address'),
  correspondence_address: sourceKeyFor('correspondence_address'),
  email: sourceKeyFor('email'),
  telephone: sourceKeyFor('telephone'),
  fax: sourceKeyFor('fax'),
  city: sourceKeyFor('city'),
  state: sourceKeyFor('state'),
  pincode: sourceKeyFor('pincode'),
  validity: sourceKeyFor('validity'),
  from: sourceKeyFor('from'),
  to: sourceKeyFor('to')
};

if (!sourceKeys.name || !sourceKeys.registration_number) {
  throw new Error(
    `SEBI_COLUMNS_NOT_FOUND. ` +
    `Detected header row at index ${headerIndex}, ` +
    `but Name/Registration No. could not be mapped.`
  );
}

const getValue = (row, field) => {
  const key = sourceKeys[field];
  return key ? clean(row[key]) : '';
};

const deduplicated = new Map();
let invalidRows = 0;

// Only process rows after the real header row.
// This prevents SEBI title/header rows from being interpreted as funds.
const dataRows = inputRows.slice(headerIndex + 1);

for (const row of dataRows) {
  const name = getValue(row, 'name');
  const registrationNumber = getValue(row, 'registration_number').toUpperCase();

  // Ignore repeated header rows and empty rows.
  if (
    !name ||
    !registrationNumber ||
    normalize(name) === 'name' ||
    normalize(registrationNumber).startsWith('registration')
  ) {
    continue;
  }

  // SEBI VCF registration numbers normally look like IN/VCF/YY-YY/NNN.
  // Keep the validation tolerant enough for minor format changes.
  const registrationValid =
    /^IN\/(?:VCF|VC)\/\d{2}-\d{2}\/\d+$/.test(registrationNumber);

  if (!registrationValid) {
    invalidRows++;
    continue;
  }

  const validity = getValue(row, 'validity');
  const registrationFrom = getValue(row, 'from');
  const registrationTo = getValue(row, 'to');
  const address = getValue(row, 'address') || getValue(row, 'correspondence_address');
  const city = getValue(row, 'city');
  const state = getValue(row, 'state');
  const pincode = getValue(row, 'pincode');

  const entity = {
    registration_number: registrationNumber,
    workspace_id: config.workspace_id,
    entity_type: 'fund',
    name,
    canonical_url: null,
    external_ids: {
      sebi_registration_no: registrationNumber
    },
    attributes: {
      registry_source: 'sebi',
      registry_source_url: config.registry_source_url,
      registry_country: config.country,
      registry_status: 'regulated_identity',
      regulatory_status: 'registered',
      activity_verification_status: 'unverified',
      registry_version: config.registry_version,
      registry_last_seen_at: new Date().toISOString(),
      ...(validity ? { registry_validity: validity } : {}),
      ...(registrationFrom ? { registration_from: registrationFrom } : {}),
      ...(registrationTo ? { registration_to: registrationTo } : {}),
      ...(address ? { registry_address: address } : {}),
      ...(city ? { registry_city: city } : {}),
      ...(state ? { registry_state: state } : {}),
      ...(pincode ? { registry_pincode: pincode } : {})
    }
  };

  // Registration number is the stable deduplication key.
  deduplicated.set(registrationNumber, entity);

  if (deduplicated.size >= maxRows) {
    break;
  }
}

if (!deduplicated.size) {
  throw new Error(
    `NO_VALID_SEBI_VCF_ROWS. ` +
    `Detected header at row ${headerIndex + 1}, ` +
    `header score=${bestHeaderScore}, ` +
    `data rows=${dataRows.length}, ` +
    `invalid rows=${invalidRows}.`
  );
}

const entities = [...deduplicated.values()];

return entities.map((entity) => ({
  json: {
    p_entity: entity,
    import_quality: {
      source_rows: inputRows.length,
      header_row: headerIndex + 1,
      data_rows: dataRows.length,
      invalid_rows: invalidRows,
      valid_rows: entities.length
    }
  }
}));

const response = $input.first().json ?? {};
const result = Array.isArray(response) ? (response[0] ?? {}) : response;
return [{ json: {
  completed: true,
  entity_id: result.entity_id ?? null,
  registration_number: result.registration_number ?? null,
  regulatory_status: result.regulatory_status ?? null,
  activity_verification_status: result.activity_verification_status ?? null,
  import_quality: null
} }];

const rows = $input.all().map((item) => item.json ?? {});
const quality = rows.find((row) => row.import_quality)?.import_quality ?? {};
return [{ json: {
  status: rows.length ? 'completed' : 'failed',
  source: 'SEBI Registered Venture Capital Funds',
  source_rows: Number(quality.source_rows ?? 0),
  valid_registry_rows: Number(quality.valid_rows ?? rows.length),
  invalid_registry_rows: Number(quality.invalid_rows ?? 0),
  regulated_funds_upserted: rows.filter((row) => row.completed).length,
  activity_claims_created: 0,
  note: 'SEBI registration resolves fund identity; recent investment activity still requires grounded evidence.'
} }];
